      {
        "parameters": {
          "method": "POST",
          "url": "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent",
          "authentication": "genericCredentialType",
          "genericAuthType": "httpHeaderAuth",
          "sendHeaders": true,
          "headerParameters": {
            "parameters": [
              {
                "name": "Content-Type",
                "value": "application/json"
              }
            ]
          },
          "sendBody": true,
          "specifyBody": "json",
          "jsonBody": "={\n  \"contents\": [\n    {\n      \"parts\": [\n        {\n          \"inline_data\": {\n            \"mime_type\": \"{{ $json.mime_type || 'application/pdf' }}\",\n            \"data\": \"{{ $json.pdfBase64 }}\"\n          }\n        },\n        {\n          \"text\": \"Sos un experto clasificador de documentos administrativos argentinos. Recibis un PDF que puede ser:\\n\\n(A) FACTURA/BOLETA de servicio CON LOS DATOS — monto y vencimiento legibles (Edenor, Edesur, Metrogas, Naturgy, Aysa, Telecentro, Movistar, Personal, expensas, ABL, Arba, Agip, alquiler, alarma, prosegur, seguros, etc.)\\n\\n(B) RECIBO o COMPROBANTE DE PAGO (ticket de pagomiscuentas, comprobante bancario, ticket Rapipago/Pago Facil, voucher de tarjeta de credito, transferencia confirmada)\\n\\n(C) NOTIFICACION_FACTURA: 'Tu factura está disponible para descargar', 'Podés acceder a tu factura', 'Tus facturas ya se encuentran disponibles'. NO trae monto/vencimiento legible — solo dice que la factura existe y hay que ir al portal a descargarla. Suelen traer CUIT, contrato y un boton 'Descargar Factura'/'Ver factura'/'Ver online'.\\n\\n(D) RECORDATORIO_PAGO: 'Tu factura sigue pendiente', 'Aboná hoy tu factura vencida', 'Regularizá'. Es un aviso de cobro de una factura ya emitida que no se pagó. Suele traer monto, referencia/contrato, link de pago.\\n\\n(E) OTRO: cualquier otra cosa.\\n\\nIMPORTANTE: si el PDF tiene un BANNER al inicio que dice 'Este documento se genero del CUERPO DEL EMAIL', es un email convertido a PDF. Setea origen_email=true. Al final del PDF hay una sección 'Links detectados' con URLs.\\n\\nDEVOLVER:\\n- tipo_documento: 'FACTURA' | 'RECIBO_PAGO' | 'NOTIFICACION_FACTURA' | 'RECORDATORIO_PAGO' | 'OTRO'\\n- confianza: 0..1\\n- origen_email: bool\\n- url_factura: string (link al portal/descarga si existe)\\n- tipo_documento_detectado: string corto descriptivo\\n- proveedor (siempre que se pueda inferir, incluso para NOTIFICACION/RECORDATORIO)\\n- numero_cliente (Nro Cliente/Cuenta/NIS/Referencia/Contrato)\\n- numero_factura (si aparece)\\n- monto_total (si aparece, si no null)\\n- fecha_emision/fecha_vencimiento/fecha_pago (según corresponda)\\n- forma_pago (solo en RECIBO_PAGO)\\n- tipo_servicio\\n- direccion_suministro\\n\\nCompat: tambien devolve es_factura=true cuando tipo_documento==='FACTURA' y confianza_es_factura igual a confianza. Para los otros tipos, es_factura=false.\\n\\nDevolve SOLO JSON.\"\n        }\n      ]\n    }\n  ],\n  \"generationConfig\": {\n    \"responseMimeType\": \"application/json\",\n    \"responseSchema\": {\n      \"type\": \"object\",\n      \"properties\": {\n        \"tipo_documento\": {\"type\": \"string\", \"enum\": [\"FACTURA\", \"RECIBO_PAGO\", \"NOTIFICACION_FACTURA\", \"RECORDATORIO_PAGO\", \"OTRO\"]},\n        \"confianza\": {\"type\": \"number\"},\n        \"origen_email\": {\"type\": \"boolean\"},\n        \"url_factura\": {\"type\": \"string\"},\n        \"es_factura\": {\"type\": \"boolean\"},\n        \"confianza_es_factura\": {\"type\": \"number\"},\n        \"tipo_documento_detectado\": {\"type\": \"string\"},\n        \"proveedor\": {\"type\": \"string\"},\n        \"cuit_emisor\": {\"type\": \"string\"},\n        \"numero_cliente\": {\"type\": \"string\"},\n        \"numero_factura\": {\"type\": \"string\"},\n        \"fecha_emision\": {\"type\": \"string\"},\n        \"fecha_vencimiento\": {\"type\": \"string\"},\n        \"fecha_pago\": {\"type\": \"string\"},\n        \"monto_total\": {\"type\": \"number\"},\n        \"direccion_suministro\": {\"type\": \"string\"},\n        \"tipo_servicio\": {\"type\": \"string\", \"enum\": [\"Electricidad\", \"Gas\", \"Agua\", \"Internet\", \"Telefonia\", \"Otro\"]},\n        \"forma_pago\": {\"type\": \"string\", \"enum\": [\"Tarjeta credito\", \"Tarjeta debito\", \"Transferencia\", \"Efectivo\", \"Debito automatico\", \"Otro\"]}\n      },\n      \"required\": [\"tipo_documento\", \"confianza\"]\n    }\n  }\n}",
          "options": {
            "response": {
              "response": {
                "responseFormat": "json"
              }
            },
            "timeout": 120000
          }
        },
        "id": "extraer-gemini",
        "name": "Extraer con Gemini",
        "position": [
          448,
          0
        ],
        "type": "n8n-nodes-base.httpRequest",
        "typeVersion": 4.4,
        "credentials": {
          "httpHeaderAuth": {
            "id": "NvYI5ygJZKl8tUgj",
            "name": "Header Auth account 2"
          }
        },
        "onError": "continueErrorOutput",
        "retryOnFail": true,
        "maxTries": 4,
        "waitBetweenTries": 60000
      },
      {
        "parameters": {
          "jsCode": "const response = $input.first().json;\n\n// Metadata del archivo: viene de Descargar PDF (Drive) o de Adapt Upload Input (manual).\nlet fileMeta = null;\ntry { fileMeta = $('Descargar PDF').first().json; } catch (e) { fileMeta = null; }\nif (!fileMeta || (!fileMeta.id && !fileMeta.name)) {\n  try { const a = $('Adapt Upload Input').first(); if (a) fileMeta = a.json; } catch (e) {}\n}\nfileMeta = fileMeta || { id: 'unknown', name: 'unknown.pdf' };\n\n// Extrae el sender_email codificado en el filename por el Apps Script.\nlet senderEmail = '';\nlet origenEmail = false;\ntry {\n  const fname = fileMeta.name || '';\n  const m = fname.match(/__from_([a-z0-9_-]+)__/i);\n  if (m && m[1]) {\n    senderEmail = m[1].replace(/_at_/g, '@').replace(/_dot_/g, '.').toLowerCase();\n  }\n  if (/email_body\\.pdf$/i.test(fname)) origenEmail = true;\n} catch (e) {}\n\nlet extracted = {};\nlet rawJson = '';\nlet parseError = null;\ntry {\n  const text = response && response.candidates && response.candidates[0] && response.candidates[0].content && response.candidates[0].content.parts && response.candidates[0].content.parts[0] && response.candidates[0].content.parts[0].text;\n  if (!text) throw new Error('Gemini no devolvio contenido');\n  rawJson = text;\n  extracted = JSON.parse(text);\n} catch (err) {\n  parseError = err.message;\n  rawJson = JSON.stringify(response);\n}\n\n// Limpieza: Gemini a veces devuelve la string 'null' / 'none' / '' en lugar de null real\nconst cleanStr = (s) => {\n  if (s == null) return null;\n  const str = String(s).trim().toLowerCase();\n  if (str === '' || str === 'null' || str === 'none' || str === 'n/a' || str === 'nan' || str === 'undefined') return null;\n  return s;\n};\n// Normaliza fechas argentinas a YYYY-MM-DD. Acepta YYYY-MM-DD, DD/MM/YYYY, DD-MM-YYYY, DD/MM/YY.\nconst parseFechaArg = (raw) => {\n  const cleaned = cleanStr(raw);\n  if (!cleaned) return null;\n  const s = String(cleaned).trim();\n  if (/^\\d{4}-\\d{2}-\\d{2}$/.test(s)) return s;\n  const m = s.match(/^(\\d{1,2})[\\/\\-](\\d{1,2})[\\/\\-](\\d{2,4})$/);\n  if (m) {\n    let d = m[1], mes = m[2], anio = m[3];\n    if (anio.length === 2) anio = '20' + anio;\n    return anio + '-' + mes.padStart(2, '0') + '-' + d.padStart(2, '0');\n  }\n  return null;\n};\n\nconst tipoDoc = cleanStr(extracted.tipo_documento)\n  || (extracted.es_factura === true ? 'FACTURA' : 'OTRO');\nconst confianza = typeof extracted.confianza === 'number' ? extracted.confianza\n               : typeof extracted.confianza_es_factura === 'number' ? extracted.confianza_es_factura\n               : 0;\nconst esFactura = tipoDoc === 'FACTURA';\nconst esRecibo  = tipoDoc === 'RECIBO_PAGO';\nconst flagOrigenEmail = origenEmail || extracted.origen_email === true;\n\nreturn [{ json: {\n  file_id: fileMeta.id,\n  file_name: fileMeta.name,\n  sender_email: senderEmail,\n  origen_email: flagOrigenEmail,\n  url_factura: cleanStr(extracted.url_factura),\n  tipo_documento: tipoDoc,\n  es_factura: esFactura,\n  es_recibo: esRecibo,\n  confianza: confianza,\n  confianza_es_factura: confianza,\n  tipo_documento_detectado: cleanStr(extracted.tipo_documento_detectado),\n  proveedor: cleanStr(extracted.proveedor),\n  cuit_emisor: cleanStr(extracted.cuit_emisor),\n  numero_cliente: cleanStr(extracted.numero_cliente),\n  numero_factura: cleanStr(extracted.numero_factura),\n  fecha_emision: parseFechaArg(extracted.fecha_emision),\n  fecha_vencimiento: parseFechaArg(extracted.fecha_vencimiento),\n  fecha_pago: parseFechaArg(extracted.fecha_pago),\n  monto_total: typeof extracted.monto_total === 'number' ? extracted.monto_total : (Number(extracted.monto_total) || null),\n  direccion_suministro: cleanStr(extracted.direccion_suministro),\n  tipo_servicio: cleanStr(extracted.tipo_servicio),\n  forma_pago: cleanStr(extracted.forma_pago),\n  raw_json: rawJson,\n  parse_error: parseError,\n  extraction_ok: parseError === null,\n  triage_pass: (esFactura || esRecibo) && confianza >= 0.6,\n  triage_recibo: esRecibo && confianza >= 0.6\n} }];"
        },
