        "parameters": {
          "jsCode": "const factura = $input.first().json;\n\n// Resuelve metadata del archivo: Descargar PDF (Drive) o Adapt Upload Input (manual).\nlet fileMeta = null;\ntry { fileMeta = $('Descargar PDF').first().json; } catch (e) { fileMeta = null; }\nif (!fileMeta || (!fileMeta.id && !fileMeta.name)) {\n  try { const a = $('Adapt Upload Input').first(); if (a) fileMeta = a.json; } catch (e) {}\n}\nfileMeta = fileMeta || { id: 'unknown', name: 'unknown.pdf' };\n\n// Truncar raw_json para no exceder el límite de 50000 chars/celda de Google Sheets\nconst MAX_RAW = 8000;\nlet rawJson = factura.raw_json || JSON.stringify(factura);\nif (rawJson && rawJson.length > MAX_RAW) {\n  rawJson = rawJson.slice(0, MAX_RAW) + '...[truncado: ' + (rawJson.length - MAX_RAW) + ' chars más]';\n}\nlet parseError = factura.parse_error || 'Gemini fallo';\nif (parseError && parseError.length > 1000) parseError = parseError.slice(0, 1000) + '...';\n\nreturn [{ json: {\n  file_id: factura.file_id || fileMeta.id,\n  file_name: factura.file_name || fileMeta.name,\n  proveedor: null,\n  cuit_emisor: null,\n  numero_cliente: null,\n  numero_factura: null,\n  fecha_emision: null,\n  fecha_vencimiento: null,\n  monto_total: null,\n  direccion_suministro: null,\n  tipo_servicio: null,\n  raw_json: rawJson,\n  parse_error: parseError\n} }];"
