          "jsCode": "const fact = $('Matching Local').first().json;\nconst drive = $input.first().json;\nconst now = new Date().toISOString();\n\nlet uploadedBy = '';\ntry {\n  const a = $('Adapt Upload Input').first();\n  if (a && a.json && a.json.uploadedBy) uploadedBy = a.json.uploadedBy;\n} catch (e) { }\n\nconst venc = fact.fecha_vencimiento || '';\nconst mes = (fact.fecha_emision || venc || now).slice(0, 7);\nconst venceDate = venc ? new Date(venc + 'T12:00:00') : null;\nconst today = new Date();\nconst estado = (venceDate && venceDate < today) ? 'VENCIDO' : 'DEUDA';\n\nconst slug = (s) => (s || '').toString().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 16);\n// ID único: parte determinística (proveedor+factura) + sufijo timestamp para garantizar unicidad.\n// La detección de duplicados se hace en el front antes de confirmar.\nconst baseId = (fact.numero_factura && fact.proveedor)\n  ? 'SVC-' + slug(fact.proveedor) + '-' + slug(fact.numero_factura)\n  : 'SVC';\nconst factId = baseId + '-' + Date.now().toString(36);\n\nconst matchedBySender = fact.match_type === 'sender_email';\nconst senderTag = matchedBySender && fact.sender_email\n  ? ' . match por email: ' + fact.sender_email\n  : '';\nconst origenTag = fact.origen_email\n  ? ' . 📩 Datos extraídos del cuerpo del email (no era PDF adjunto)'\n  : '';\nconst urlTag = fact.url_factura\n  ? ' . Link al portal: ' + fact.url_factura\n  : '';\n\nreturn [{ json: {\n  id: factId,\n  mes,\n  local: fact.local_nombre || '',\n  servicio: fact.proveedor || fact.match_servicio || '',\n  monto: Number(fact.monto_total) || 0,\n  vence: venc,\n  estado,\n  pago: '',\n  forma: '',\n  cliente: fact.numero_cliente ? String(fact.numero_cliente) : '',\n  titular: fact.match_titular || '',\n  tel: fact.match_tel || '',\n  user: fact.match_user || '',\n  pass: fact.match_pass || '',\n  obs: 'N. factura: ' + (fact.numero_factura || '-') + (fact.cuit_emisor ? ' . CUIT: ' + fact.cuit_emisor : '') + (uploadedBy ? ' . Subida manual por ' + uploadedBy : '') + senderTag + origenTag + urlTag,\n  pdf_url: drive.webViewLink || (drive.id && !String(drive.id).startsWith('manual-') ? 'https://drive.google.com/file/d/' + drive.id + '/view' : ''),\n  ia_confianza: matchedBySender ? 0.7 : 0.9,\n  ia_revisado: false,\n  created_at: now,\n  updated_at: now,\n  created_by: uploadedBy || 'IA',\n  updated_by: uploadedBy || ''\n} }];"
