icio: parsed.tipo_servicio,\n    direccion_suministro: parsed.direccion_suministro,\n    tipo_documento_detectado: parsed.tipo_documento_detectado,\n    es_factura: parsed.es_factura,\n    confianza: parsed.confianza_es_factura,\n    sender_email: parsed.sender_email || null,\n    origen_email: parsed.origen_email || false,\n    url_factura: parsed.url_factura || null,\n    file_name: parsed.file_name || null,\n    uploaded_by: uploadedBy || null\n  }),\n  motivo,\n  ia_confianza: parsed.confianza_es_factura || 0.5,\n  created_at: now,\n  resuelto: 'FALSE',\n  resolved_at: ''\n} }];"
