        "parameters": {
          "mode": "runOnceForAllItems",
          "jsCode": "const recibo = $('Parsear JSON Gemini').first().json;\nconst facturas = $input.all().map(function(i){ return i.json; });\n\nlet uploadedBy = '';\ntry { const a = $('Adapt Upload Input').first(); if (a && a.json) uploadedBy = a.json.uploadedBy || ''; } catch (e) {}\n\nconst normName = (v) => (v || '').toString().trim().toLowerCase().replace(/[^a-z0-9]+/g, '');\nconst onlyDigits = (v) => (v || '').toString().replace(/\\D+/g, '').replace(/^0+/, '');\n\nconst rProv = normName(recibo.proveedor);\nconst rCli  = onlyDigits(recibo.numero_cliente);\nconst rFac  = (recibo.numero_factura || '').toString().trim();\nconst rMon  = Number(recibo.monto_total) || 0;\n\n// Solo facturas pendientes (DEUDA o VENCIDO)\nconst pendientes = facturas.filter(function(f){\n  const e = (f.estado || '').toString().toUpperCase();\n  return e === 'DEUDA' || e === 'VENCIDO';\n});\n\nfunction scoreFactura(f) {\n  let s = 0;\n  const fProv = normName(f.servicio);\n  const fCli  = onlyDigits(f.cliente);\n  const fMon  = Number(f.monto) || 0;\n  if (rProv && fProv && (fProv.indexOf(rProv) >= 0 || rProv.indexOf(fProv) >= 0)) s += 3;\n  if (rCli && fCli && rCli === fCli) s += 4;\n  if (rFac && f.obs && String(f.obs).indexOf(rFac) >= 0) s += 5;\n  if (rMon > 0 && fMon > 0) {\n    const diff = Math.abs(fMon - rMon) / Math.max(fMon, rMon);\n    if (diff < 0.02) s += 4;\n    else if (diff < 0.05) s += 2;\n    else if (diff < 0.10) s += 1;\n  }\n  return s;\n}\n\nconst scored = pendientes.map(function(f){ return { factura: f, score: scoreFactura(f) }; });\nscored.sort(function(a,b){ return b.score - a.score; });\nconst best = scored[0];\nconst MIN_SCORE = 5;\n\nif (!best || best.score < MIN_SCORE) {\n  return [{ json: {\n    matched: false,\n    motivo: best ? ('Recibo de pago sin factura matching (mejor score=' + best.score + ')') : 'Recibo sin facturas pendientes',\n    recibo: recibo,\n    uploadedBy: uploadedBy\n  } }];\n}\n\nconst f = best.factura;\nconst now = new Date().toISOString();\nreturn [{ json: {\n  matched: true,\n  factura_id: f.id,\n  servicio_matched: f.servicio,\n  local_matched: f.local,\n  score_match: best.score,\n  pago: recibo.fecha_pago || now.slice(0, 10),\n  forma: recibo.forma_pago || 'Otro',\n  monto: f.monto,\n  uploadedBy: uploadedBy,\n  recibo: recibo\n} }];"
