        {
          "parameters": {
            "jsCode": "const factura = $('Parsear JSON Gemini').first().json;\nconst cuentas = $input.all().map(function(i){ return i.json; });\n\nconst normName = (v) => (v || '').toString().trim().toLowerCase().replace(/[^a-z0-9]+/g, '');\nconst onlyDigits = (v) => (v || '').toString().replace(/\\D+/g, '').replace(/^0+/, '');\nconst normEmail = (v) => (v || '').toString().trim().toLowerCase();\n\nconst factProv    = normName(factura.proveedor);\nconst factCliente = onlyDigits(factura.numero_cliente);\nconst factSender  = normEmail(factura.sender_email);\n\n// 1) Match por n_cliente exacto + proveedor coincidente (lo de antes, más fuerte)\nlet match = cuentas.find(function(row){\n  const rowSvc = normName(row.servicio);\n  const rowCliente = onlyDigits(row.n_cliente);\n  if (!rowCliente || !factCliente) return false;\n  if (rowCliente !== factCliente) return false;\n  return factProv.includes(rowSvc) || rowSvc.includes(factProv);\n});\nlet matchType = match ? 'n_cliente' : null;\n\n// 2) Fallback: match por sender_email (útil para avisos donde el PDF no trae n_cliente legible)\nif (!match && factSender) {\n  match = cuentas.find(function(row){\n    return normEmail(row.sender_email) === factSender;\n  });\n  if (match) matchType = 'sender_email';\n}\n\nreturn [{ json: Object.assign({}, factura, {\n  local_nombre: match ? match.local : null,\n  estado_matching: match ? 'OK' : 'SIN_MATCH',\n  match_type: matchType,\n  match_titular: match && match.titular ? match.titular : null,\n  match_tel: match && match.tel ? match.tel : null,\n  match_user: match && match.user ? match.user : null,\n  match_pass: match && match.pass ? match.pass : null,\n  match_servicio: match && match.servicio ? match.servicio : null\n}) }];"
