            "jsCode": "const inp = $input.first().json;\nconst body = inp.body || { };\nif (!body.base64) {\n  throw new Error('Missing base64 in request body');\n}\nconst filename = body.filename || ('upload-' + Date.now() + '.pdf');\nconst userEmail = ((inp._authUser) || { }).email || 'unknown';\n\n// Detectar mime: prioriza el body, después la extensión del filename\nlet mimeType = (body.mime_type || '').toLowerCase();\nif (!mimeType) {\n  const fn = filename.toLowerCase();\n  if (fn.endsWith('.pdf')) mimeType = 'application/pdf';\n  else if (fn.endsWith('.jpg') || fn.endsWith('.jpeg')) mimeType = 'image/jpeg';\n  else if (fn.endsWith('.png')) mimeType = 'image/png';\n  else if (fn.endsWith('.heic') || fn.endsWith('.heif')) mimeType = 'image/heic';\n  else if (fn.endsWith('.webp')) mimeType = 'image/webp';\n  else mimeType = 'application/pdf';\n}\n\nconst buffer = Buffer.from(body.base64, 'base64');\nconst binaryData = await this.helpers.prepareBinaryData(buffer, filename, mimeType);\n\nreturn [{\n  json: {\n    id: 'manual-' + Date.now(),\n    name: filename,\n    webViewLink: '',\n    uploadedBy: userEmail,\n    mime_type: mimeType,\n    _source: 'upload'\n  },\n  binary: { data: binaryData }\n}];"
